// =============================================================================
// Signal Types - Trading signal data structures
// =============================================================================

import type { SignalAction, Timeframe, TradingSymbol } from './common';

/**
 * Trading signal generated by ML model
 */
export interface Signal {
  id: string;
  symbol: TradingSymbol;
  timeframe: Timeframe;
  action: SignalAction;
  confidence: number; // 0-100
  price: number;
  timestamp: string;
  indicators: SignalIndicators;
  modelVersion: string;
}

/**
 * Technical indicators used in signal generation
 */
export interface SignalIndicators {
  rsi: number;
  macd: MacdIndicator;
  bollingerBands: BollingerBands;
  ema20: number;
  ema50: number;
  volume24h: number;
  volumeChange: number;
}

/**
 * MACD indicator values
 */
export interface MacdIndicator {
  value: number;
  signal: number;
  histogram: number;
}

/**
 * Bollinger Bands indicator
 */
export interface BollingerBands {
  upper: number;
  middle: number;
  lower: number;
}

/**
 * Real-time sentiment data (displayed separately from ML signal)
 */
export interface SentimentData {
  symbol: TradingSymbol;
  score: number; // -1 to 1 (negative to positive)
  label: 'bearish' | 'neutral' | 'bullish';
  sources: SentimentSource[];
  timestamp: string;
}

/**
 * Individual sentiment source
 */
export interface SentimentSource {
  name: string; // e.g., "Twitter", "Reddit", "News"
  score: number;
  articleCount: number;
}

/**
 * Signal history entry for tracking performance
 */
export interface SignalHistoryEntry {
  signal: Signal;
  actualOutcome: SignalAction | null;
  priceAtOutcome: number | null;
  profitLoss: number | null;
  isCorrect: boolean | null;
}
